
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b3p86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b3p86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.529018322205343e+00, -3.462517361582479e+00, -3.369368473756287e+00, -3.240408502015431e+00, -3.064843334431433e+00, -2.831522230787900e+00, -2.531952871261436e+00, -2.165728608255887e+00, -1.747745785403470e+00, -1.311318065940542e+00, -8.907179672699912e-01, -6.134774829123867e-01, -5.339913039581283e-01, -4.416086487883612e-01, -3.203923040636062e-01, -2.029545335286889e-01, -1.201541916011777e-01, -7.946121106778531e-02, -4.763095365488361e-02, -3.062332439711928e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


